package com.proofclean.analysis.dto;
import com.proofclean.analysis.entity.*;import java.time.LocalDateTime;import java.util.List;
public record AnalysisDetailResponse(Long id, String title, AnalysisPurpose purpose, AnalysisStatus status, Integer riskScore, String summary, LocalDateTime createdAt, List<UploadedFileResponse> files, List<DetectionDto> findings, List<RiskScenarioDto> scenarios, List<RecommendationDto> recommendations, List<MaskedFileResponse> maskedFiles) { public static AnalysisDetailResponse from(AnalysisProject p){ return new AnalysisDetailResponse(p.getId(),p.getTitle(),p.getPurpose(),p.getStatus(),p.getRiskScore(),p.getSummary(),p.getCreatedAt(),p.getFiles().stream().map(UploadedFileResponse::from).toList(),p.getFindings().stream().map(DetectionDto::from).toList(),p.getScenarios().stream().map(RiskScenarioDto::from).toList(),p.getRecommendations().stream().map(RecommendationDto::from).toList(),p.getMaskedFiles().stream().map(MaskedFileResponse::from).toList()); } }
